const studioParams=new URLSearchParams(location.search),requestedProduct=studioParams.get('product')||'',requestedOccasion=occasionSlugMap[studioParams.get('occasion')||'']||productOccasionMap[requestedProduct]||'Anniversary';
function coversForOccasion(name){const group=occasionGroupMap[name]||'couples',matched=catalogCovers.filter(cover=>cover.group===group);return matched.length?matched:catalogCovers.filter(cover=>cover.group==='couples')}
function coverSource(id,stored){if(stored&&!String(id).startsWith('classic-'))return stored;return catalogCovers.find(cover=>cover.id===id)?.src||catalogCovers[0]?.src||''}
