let state={step:0,hasStarted:false,draftId:crypto.randomUUID?.()||`draft-${Date.now()}`,productHandle:requestedProduct,occasion:requestedOccasion,cover:initialCover.id,coverName:initialCover.name,coverSrc:initialCover.src,title:'Our Story',subtitle:'',personalization:{values:{title:'Our Story',subtitle:'',name:'',age:''},added:[],custom:[],coverId:initialCover.id},coverPhotos:[],size:'Regular',pages:20,basePrice:2799,pagePrice:75,photos:[],items:[],overlays:[],pageBackgrounds:{},activePage:0,selectedItemId:null,selectedOverlayId:null,nextItemId:1,nextOverlayId:1,currentSpread:0,designMode:'custom'};
