occasions.forEach(([name,image],index)=>{const b=document.createElement('button');b.className='occasion-card occasion-'+index+(name===state.occasion?' selected':'');b.innerHTML=`<span class="occasion-art"><img src="${image}" alt="" loading="lazy" decoding="async"></span><b>${name}</b>`;b.onclick=()=>{state.occasion=name;state.productHandle=Object.keys(productOccasionMap).find(handle=>productOccasionMap[handle]===name)||state.productHandle;document.querySelectorAll('.occasion-card').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');tapFeedback();renderOccasionContext();renderSuggestions();};occasionGrid.append(b)});
function chooseCover(cover,card,feedback=true){state.cover=cover.id;state.coverName=cover.name;state.coverSrc=cover.src;document.body.classList.toggle('catalog-cover',cover.group!=='classic');document.querySelectorAll('.cover-option').forEach(x=>x.classList.toggle('selected',x===card));card?.scrollIntoView({inline:'center',block:'nearest',behavior:'smooth'});document.querySelectorAll('.book-mockup>img').forEach(img=>img.src=cover.src);document.querySelector('#selectedCoverName').textContent=cover.name;if(document.querySelector('#personalizationFields')?.dataset.ready==='true')renderPersonalizationForm();if(feedback)tapFeedback()}
function renderCoverOptions(preserve=false){const list=coversForOccasion(state.occasion);coverGrid.innerHTML='';let selected=list.find(cover=>preserve&&cover.id===state.cover)||list[0];list.forEach((cover,index)=>{const b=document.createElement('button');b.type='button';b.className='cover-option'+(cover.id===selected.id?' selected':'');b.dataset.coverId=cover.id;b.innerHTML=`<span class="cover-thumb"><img src="${cover.src}" alt="${cover.name} cover" loading="lazy" decoding="async"><i aria-hidden="true">✓</i><em class="match-badge">${index<3?'Recommended':''}</em></span><span class="cover-meta"><small>Cover ${String(index+1).padStart(2,'0')}</small><b>${cover.name}</b></span>`;b.onclick=()=>chooseCover(cover,b);coverGrid.append(b)});chooseCover(selected,coverGrid.querySelector('.selected'),false)}
function renderOccasionContext({preserve=false}={}){const context=occasionContext[state.occasion]||occasionContext.Anniversary;document.body.dataset.occasion=state.occasion;document.querySelectorAll('.occasion-card').forEach(card=>card.classList.toggle('selected',card.textContent.trim()===state.occasion));document.querySelector('#coverEyebrow').textContent=context.eyebrow;document.querySelector('#coverHeading').textContent=context.heading;document.querySelector('#coverCopy').textContent=context.copy;const next=document.querySelector('.occasion-next');next.style.setProperty('--occasion-image',`url("${occasionImages[state.occasion]}")`);next.querySelector('b').textContent=context.cta;renderCoverOptions(preserve);renderBackgroundEdition()}
renderOccasionContext();

function tapFeedback(){if('vibrate' in navigator)navigator.vibrate(8)}
function go(step){if(state.step===2&&step>2&&!validatePersonalization())return;state.step=Math.max(0,Math.min(4,step));if(state.step>0)state.hasStarted=true;document.body.classList.toggle('journey-started',state.hasStarted);document.body.classList.toggle('studio-immersive',state.step===4);panels.forEach((p,i)=>p.classList.toggle('active',i===state.step));progress.forEach((p,i)=>{p.classList.toggle('active',i===state.step);p.classList.toggle('complete',i<state.step)});const nav=document.querySelector('.progress');const active=progress[state.step];nav.scrollTo({left:active.offsetLeft-(nav.clientWidth-active.clientWidth)/2,behavior:'smooth'});scrollTo({top:0,behavior:'smooth'});tapFeedback();if(state.step===2){renderPersonalizationForm();renderSuggestions()}if(state.step===4)requestAnimationFrame(()=>window.dispatchEvent(new CustomEvent('june:studio-open')))}
document.querySelectorAll('.next').forEach(b=>b.onclick=()=>go(state.step+1));
document.querySelectorAll('.back').forEach(b=>b.onclick=()=>go(state.step-1));
progress.forEach((b,i)=>b.onclick=()=>go(i));

const titleInput=document.querySelector('#albumTitle');
const subtitleInput=document.querySelector('#albumSubtitle');
function escapeHtml(value){return String(value??'').replace(/[&<>'"]/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[character]))}
const personalizationDefinitions={title:{label:'Title',placeholder:'Your story title',max:36,lines:2},subtitle:{label:'Subtitle',placeholder:'A date, place or short dedication',max:48,lines:2},name:{label:'Name',placeholder:'The name to print',max:20,lines:1},age:{label:'Age',placeholder:'e.g. 40',max:3,lines:1}};
function personalizationSchema(){return window.JUNE_COVER_PERSONALIZATION?.[state.cover]||{fields:[{...personalizationDefinitions.title,key:'title',required:true},{...personalizationDefinitions.subtitle,key:'subtitle',required:true}],photoSlots:1,proofRequired:true}}
function normalizePersonalization(){const previous=state.personalization||{},values={title:state.title||'Our Story',subtitle:state.subtitle||'',name:'',age:'',...(previous.values||{})};state.personalization={values,added:Array.isArray(previous.added)?previous.added:[],custom:Array.isArray(previous.custom)?previous.custom:[],coverId:state.cover};state.coverPhotos=Array.isArray(state.coverPhotos)?state.coverPhotos:[]}
function activePersonalizationKeys(){const required=personalizationSchema().fields.map(field=>field.key);return[...new Set([...required,...state.personalization.added])].filter(key=>personalizationDefinitions[key])}
function fieldSpecification(key){return personalizationSchema().fields.find(field=>field.key===key)||{...personalizationDefinitions[key],key,required:false}}
function setPersonalizationValue(key,value){normalizePersonalization();state.personalization.values[key]=String(value||'').slice(0,fieldSpecification(key).max||personalizationDefinitions[key]?.max||36);renderPersonalizationPreview();const input=document.querySelector(`[data-personalization-key="${key}"]`);if(input&&input.value!==state.personalization.values[key])input.value=state.personalization.values[key];const count=input?.closest('.personalization-field')?.querySelector('[data-field-count]');if(count)count.textContent=`${state.personalization.values[key].length} / ${input.maxLength}`;queueDraftSave()}
function renderPersonalizationPreview(){normalizePersonalization();const active=activePersonalizationKeys(),values=state.personalization.values;titleInput.value=values.title||'';subtitleInput.value=values.subtitle||'';state.title=((active.includes('title')&&values.title)||(active.includes('name')&&values.name)||state.coverName||'Your Story').trim();state.subtitle=(active.includes('subtitle')?values.subtitle:'').trim();document.querySelectorAll('.cover-title').forEach(x=>x.textContent=active.includes('title')?(values.title||''):'' );document.querySelectorAll('.cover-subtitle').forEach(x=>x.textContent=active.includes('subtitle')?(values.subtitle||''):'' );document.querySelectorAll('.cover-name').forEach(x=>x.textContent=active.includes('name')?(values.name||''):'' );document.querySelectorAll('.cover-age').forEach(x=>x.textContent=active.includes('age')?(values.age||''):'' );document.querySelector('#dialogTitle').textContent=state.title;const layer=document.querySelector('#coverPhotoPreviewLayer');if(layer){const slots=personalizationSchema().photoSlots||0;layer.className=`cover-photo-preview-layer slots-${Math.min(4,slots)}`;layer.innerHTML='';state.coverPhotos.slice(0,slots).forEach(photo=>{if(!photo?.url)return;const image=document.createElement('img');image.src=photo.url;image.alt='Cover photo placement preview';layer.append(image)})}}
function renderPersonalizationForm(){normalizePersonalization();const schema=personalizationSchema(),requiredKeys=schema.fields.map(field=>field.key);state.coverPhotos=state.coverPhotos.slice(0,schema.photoSlots||0);const fields=document.querySelector('#personalizationFields');fields.innerHTML='';activePersonalizationKeys().forEach(key=>{const spec=fieldSpecification(key),row=document.createElement('div'),value=state.personalization.values[key]||'';row.className=`personalization-field ${spec.lines>1?'is-wide':''} ${requiredKeys.includes(key)?'is-required':''}`;row.innerHTML=`<label for="personalization-${key}"><span>${spec.label}${requiredKeys.includes(key)?'':' · optional'}</span><small data-field-count>${value.length} / ${spec.max}</small></label><input id="personalization-${key}" data-personalization-key="${key}" maxlength="${spec.max}" value="${escapeHtml(value)}" placeholder="${escapeHtml(spec.placeholder||'')}"><button type="button" class="remove-personalization" aria-label="Remove ${spec.label}">×</button>`;const input=row.querySelector('input');input.oninput=()=>setPersonalizationValue(key,input.value);row.querySelector('.remove-personalization').onclick=()=>{state.personalization.added=state.personalization.added.filter(item=>item!==key);state.personalization.values[key]='';renderPersonalizationForm();queueDraftSave()};fields.append(row)});state.personalization.custom.forEach(custom=>{const row=document.createElement('div');row.className='personalization-field is-wide';row.innerHTML=`<label><input class="custom-field-label" aria-label="Custom field name" maxlength="24" value="${escapeHtml(custom.label||'Custom detail')}"><small data-field-count>${String(custom.value||'').length} / ${custom.max||36}</small></label><input class="custom-field-value" maxlength="${custom.max||36}" value="${escapeHtml(custom.value||'')}" placeholder="Add your own wording"><button type="button" class="remove-personalization" aria-label="Remove custom detail">×</button>`;row.querySelector('.custom-field-label').oninput=event=>{custom.label=event.target.value;queueDraftSave()};row.querySelector('.custom-field-value').oninput=event=>{custom.value=event.target.value;row.querySelector('[data-field-count]').textContent=`${custom.value.length} / ${custom.max||36}`;queueDraftSave()};row.querySelector('.remove-personalization').onclick=()=>{state.personalization.custom=state.personalization.custom.filter(item=>item.id!==custom.id);renderPersonalizationForm();queueDraftSave()};fields.append(row)});const optional=document.querySelector('#optionalFieldChoices');optional.innerHTML='';Object.keys(personalizationDefinitions).filter(key=>!activePersonalizationKeys().includes(key)).forEach(key=>{const button=document.createElement('button');button.type='button';button.textContent=`+ ${personalizationDefinitions[key].label}`;button.onclick=()=>{state.personalization.added.push(key);renderPersonalizationForm();queueDraftSave()};optional.append(button)});const customButton=document.createElement('button');customButton.type='button';customButton.textContent='+ Custom detail';customButton.onclick=()=>{state.personalization.custom.push({id:crypto.randomUUID?.()||`custom-${Date.now()}`,label:'Custom detail',value:'',max:36});renderPersonalizationForm();queueDraftSave()};optional.append(customButton);renderCoverPhotoFields();renderPersonalizationPreview();renderSuggestions()}
function renderCoverPhotoFields(){const schema=personalizationSchema(),section=document.querySelector('#coverPhotoSection'),container=document.querySelector('#coverPhotoFields'),slots=schema.photoSlots||0;section.hidden=!slots;document.querySelector('#coverPhotoRequirement').textContent=`${slots} ${slots===1?'photo':'photos'} required for this cover`;container.innerHTML='';for(let index=0;index<slots;index++){const photo=state.coverPhotos[index],label=document.createElement('label');label.className='cover-photo-upload';label.innerHTML=`<input type="file" accept="image/jpeg,image/png,image/heic,image/heif"><span>${photo?'Replace':'Add'} cover photo ${index+1}</span>${photo?.url?`<img src="${photo.url}" alt="Cover photo ${index+1}">`:''}`;label.querySelector('input').onchange=event=>{const file=event.target.files?.[0];if(!file)return;const existing=state.coverPhotos[index];if(existing?.url?.startsWith('blob:'))URL.revokeObjectURL(existing.url);const photo={id:crypto.randomUUID?.()||`cover-photo-${Date.now()}-${index}`,name:file.name,blob:file,url:URL.createObjectURL(file),cloudStatus:'pending',slot:index};state.coverPhotos[index]=photo;const image=new Image();image.onload=()=>{photo.width=image.naturalWidth;photo.height=image.naturalHeight;renderCoverPhotoFields();renderPersonalizationPreview();queuePhotoCloudUpload(photo).catch(error=>console.error('Cover photo upload failed',error));queueDraftSave(0)};image.src=photo.url};container.append(label)}}
function personalizationSummary(){normalizePersonalization();const entries=activePersonalizationKeys().map(key=>[fieldSpecification(key).label,state.personalization.values[key]]).filter(([,value])=>value);state.personalization.custom.filter(field=>field.value).forEach(field=>entries.push([field.label||'Custom detail',field.value]));return entries.map(([label,value])=>`${label}: ${value}`).join(' | ')}
function validatePersonalization(){normalizePersonalization();const missingFields=personalizationSchema().fields.filter(field=>field.required&&!String(state.personalization.values[field.key]||'').trim()),slots=personalizationSchema().photoSlots||0,missingPhotos=Math.max(0,slots-state.coverPhotos.filter(Boolean).length),error=document.querySelector('#personalizationError');document.querySelectorAll('[data-personalization-key]').forEach(input=>input.removeAttribute('aria-invalid'));missingFields.forEach(field=>document.querySelector(`[data-personalization-key="${field.key}"]`)?.setAttribute('aria-invalid','true'));document.querySelectorAll('.cover-photo-upload').forEach((upload,index)=>upload.classList.toggle('is-missing',index>=state.coverPhotos.length||!state.coverPhotos[index]));if(!missingFields.length&&!missingPhotos){error.hidden=true;return true}const parts=[];if(missingFields.length)parts.push(`add ${missingFields.map(field=>field.label.toLowerCase()).join(' and ')}`);if(missingPhotos)parts.push(`upload ${missingPhotos} more cover ${missingPhotos===1?'photo':'photos'}`);error.textContent=`Before continuing, ${parts.join(' and ')}.`;error.hidden=false;error.scrollIntoView({block:'nearest',behavior:'smooth'});tapFeedback();return false}
function renderTitle(){normalizePersonalization();state.personalization.values.title=titleInput.value||state.personalization.values.title||'';state.personalization.values.subtitle=subtitleInput.value||state.personalization.values.subtitle||'';renderPersonalizationPreview()}
function renderSuggestions(){document.querySelector('#suggestionOccasion').textContent=state.occasion;const box=document.querySelector('#suggestions'),label=box.previousElementSibling,hasTitle=activePersonalizationKeys().includes('title');box.hidden=!hasTitle;if(label)label.hidden=!hasTitle;box.innerHTML='';if(!hasTitle)return;(titleIdeas[state.occasion]||titleIdeas.Anniversary).forEach(t=>{const b=document.createElement('button');b.type='button';b.className='suggestion';b.textContent=t;b.onclick=()=>setPersonalizationValue('title',t);box.append(b)})}
