function photoFilter(a={}){return `brightness(${100+(a.brightness||0)}%) contrast(${100+(a.contrast||0)}%) saturate(${100+(a.saturation||0)}%) sepia(${Math.max(0,a.warmth||0)}%) hue-rotate(${a.tint||0}deg) grayscale(${a.grayscale||0}%) blur(${a.blur||0}px)`}
function renderOverlay(pageElement,item){
  const layer=document.createElement('div');
  layer.className=`design-layer layer-${item.kind}`+(item.id===state.selectedOverlayId?' selected':'');
  layer.dataset.overlayId=item.id;
  layer.style.cssText=`left:${item.x}%;top:${item.y}%;width:${item.w}%;height:${item.h}%;transform:rotate(${item.rotation||0}deg);opacity:${item.kind==='sticker'?(item.opacity??1):1};z-index:${item.z||5}`;
  if(item.kind==='sticker'){
    layer.innerHTML=`${stickerMarkup(item.content)}<i class="layer-move-handle" aria-label="Move illustration"><svg class="studio-ui-icon" aria-hidden="true"><use href="#i-align-middle"/></svg></i><button type="button" class="layer-tools-handle" aria-label="Illustration tools"><svg class="studio-ui-icon" aria-hidden="true"><use href="#i-adjust"/></svg></button><i class="resize-handle" aria-label="Resize illustration"></i><i class="rotate-handle" aria-label="Rotate illustration"><svg class="studio-ui-icon" aria-hidden="true"><use href="#i-rotate-right"/></svg></i>`;layer.querySelector('.placed-illustration').style.transform=`scaleX(${item.flipX?-1:1})`;
  }else{
    layer.innerHTML=`<i class="layer-move-handle" aria-label="Drag to move text"><svg class="studio-ui-icon" aria-hidden="true"><use href="#i-align-middle"/></svg></i><button type="button" class="layer-tools-handle" aria-label="Edit text and style">Aa</button><span class="editable-text" contenteditable="false" role="textbox" tabindex="0" aria-label="${item.kind}. Drag to move; double-click to edit" spellcheck="true">${item.content}</span><i class="resize-handle" aria-label="Resize text"></i><i class="rotate-handle" aria-label="Rotate text"><svg class="studio-ui-icon" aria-hidden="true"><use href="#i-rotate-right"/></svg></i>`;
    const textStyle=item.textStyle||{};const textNode=layer.querySelector('.editable-text');textNode.style.cssText=`font-family:${textStyle.font||'Poppins'},Arial,sans-serif;font-size:${textStyle.size||24}px;font-weight:${textStyle.weight||800};color:${textStyle.color||'#171717'};text-align:${textStyle.align||'center'};letter-spacing:${textStyle.spacing||0}px;line-height:${textStyle.lineHeight||1.1};opacity:${textStyle.opacity??1}`;
    const editor=layer.querySelector('.editable-text');
    editor.addEventListener('dblclick',e=>{e.preventDefault();e.stopPropagation();selectOverlay(item.id,layer);startTextEditing(item,layer)});
    editor.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key==='F2')&&!layer.classList.contains('editing-text')){e.preventDefault();startTextEditing(item,layer)}});
    editor.addEventListener('input',()=>{item.content=editor.textContent});
    editor.addEventListener('blur',()=>stopTextEditing(item,layer));
  }
  const toolsHandle=layer.querySelector('.layer-tools-handle');toolsHandle.addEventListener('pointerdown',e=>e.stopPropagation());toolsHandle.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();selectOverlay(item.id,layer);window.dispatchEvent(new CustomEvent('june:overlay-tools',{detail:{id:item.id}}))});
  layer.addEventListener('pointerdown',e=>{if(layer.classList.contains('editing-text')&&e.target.closest('.editable-text'))return;const mode=e.target.classList.contains('resize-handle')?'resize':'move';beginOverlayManipulation(e,item,layer,mode)});
  layer.addEventListener('click',()=>selectOverlay(item.id,layer));
  enablePinch(layer,item);pageElement.append(layer);
}
function startTextEditing(item,layer){if(!item||!layer||item.kind==='sticker')return false;const editor=layer.querySelector('.editable-text');if(!editor)return false;layer.classList.add('editing-text');editor.contentEditable='true';editor.setAttribute('aria-label',`Editing ${item.kind}`);editor.focus({preventScroll:true});requestAnimationFrame(()=>{const selection=getSelection(),range=document.createRange();range.selectNodeContents(editor);selection.removeAllRanges();selection.addRange(range)});return true}
function stopTextEditing(item,layer){const editor=layer?.querySelector('.editable-text');if(!editor)return;item.content=editor.textContent.trim()||'Add your text';editor.textContent=item.content;editor.contentEditable='false';editor.setAttribute('aria-label',`${item.kind}. Drag to move; double-click to edit`);layer.classList.remove('editing-text');queueDraftSave()}
function editOverlayText(id){const item=state.overlays.find(overlay=>overlay.id===id),layer=document.querySelector(`.design-layer[data-overlay-id="${id}"]`);return startTextEditing(item,layer)}
function selectOverlay(id,layer){state.selectedOverlayId=id;state.selectedItemId=null;document.querySelectorAll('.design-layer').forEach(x=>x.classList.toggle('selected',Number(x.dataset.overlayId)===id));document.querySelector('#contextToolbar').hidden=true;document.querySelector('#layerOrderMenu').hidden=true;document.querySelector('#pageToolbar').hidden=true;if(layer)layer.classList.add('selected')}

