function drawPdfBackground(ctx,pageIndex){const background=state.pageBackgrounds[pageIndex],edition=backgroundEdition();ctx.fillStyle=edition.colors[3];ctx.fillRect(0,0,900,900);if(background?.type==='library'&&background.value!=='none'){ctx.globalAlpha=.38;ctx.fillStyle=edition.colors[1];ctx.fillRect(0,0,900,900);ctx.fillStyle=edition.colors[0];for(let y=45;y<900;y+=120)for(let x=(y/120%2)*55;x<900;x+=120){ctx.beginPath();ctx.arc(x,y,16,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}return background}
