async function drawPdfOverlay(ctx,item){const x=item.x*9,y=item.y*9,w=item.w*9,h=item.h*9,t=item.textStyle||{};ctx.save();ctx.translate(x+w/2,y+h/2);ctx.rotate((item.rotation||0)*Math.PI/180);ctx.globalAlpha=item.kind==='sticker'?(item.opacity??1):(t.opacity??1);ctx.fillStyle=t.color||'#171717';ctx.textAlign=t.align||'center';ctx.textBaseline='middle';if(item.kind==='sticker'){const index=Math.max(0,illustrationCatalog.findIndex(entry=>entry[0]===item.content)),sprite=await loadPdfImage(illustrationSprite),cellWidth=sprite.naturalWidth/8,cellHeight=sprite.naturalHeight/5,sourceX=(index%8)*cellWidth,sourceY=Math.floor(index/8)*cellHeight;ctx.scale(item.flipX?-1:1,1);ctx.drawImage(sprite,sourceX,sourceY,cellWidth,cellHeight,-w/2,-h/2,w,h)}else{ctx.font=`${t.weight||800} ${Math.max(18,Math.min(96,t.size||h*.48))}px ${t.font||'Poppins'}, Arial`;const words=String(item.content).split(' ');let line='',lines=[];for(const word of words){const test=line?`${line} ${word}`:word;if(ctx.measureText(test).width>w&&line){lines.push(line);line=word}else line=test}if(line)lines.push(line);const lineHeight=(t.size||44)*(t.lineHeight||1.1),textX=(t.align==='left'?-w/2:t.align==='right'?w/2:0);lines.slice(0,4).forEach((text,index)=>ctx.fillText(text,textX,(index-(lines.length-1)/2)*lineHeight))}ctx.restore()}
