  const output=state.size==='Large'?3300:2400,canvas=document.createElement('canvas');canvas.width=canvas.height=output;const ctx=canvas.getContext('2d');ctx.scale(output/900,output/900);const background=drawPdfBackground(ctx,pageIndex);
